frappe.ui.form.on('Work Team', {
  onload: function (frm) {
    const html = `
      <label style="display:block; margin-bottom:5px;">Specialization</label>
      <div style="margin-bottom:45px;"  class="multi-select-container">
        <div class="multi-select-box" onclick="toggleOptions()" id="multi-select-box">
          <span class="selected-values" id="selected-values"></span>
        </div>
        <div class="multi-select-options" id="multi-select-options">
          <div class="option" data-value="Clearing">Clearing</div>
          <div class="option" data-value="Planting">Planting</div>
          <div class="option" data-value="Planning">Planning</div>
          <div class="option" data-value="Reporting">Reporting</div>
        </div>
      </div>
    `;

    const css = `
      <style>
        .multi-select-container {
          position: relative;
          width: 500px;
        }
        .multi-select-box {
          border: 1px solid #f3f3f3;
          padding: 6px;
          background-color: #F3F3F3;
          cursor: pointer;
          border-radius: 8px;
          min-height: 28px;
        }
        .selected-chip {
          display: inline-block;
          background: #dedede;
          color: #333;
          padding: 2px 6px;
          margin-right: 5px;
          margin-bottom: 3px;
          border-radius: 5px;
          font-size: 12px;
          cursor: pointer;
        }
        .multi-select-options {
          display: none;
          border: 1px solid #f3f3f3;
          border-top: none;
          background: #fff;
          position: absolute;
          width: 100%;
          z-index: 100;
          box-shadow: 0 4px 8px rgba(0,0,0,0.1);
          max-height: 150px;
          overflow-y: auto;
        }
        .multi-select-options .option {
          padding: 8px 10px;
          cursor: pointer;
        }
        .multi-select-options .option:hover {
          background: #f0f0f0;
        }
        .multi-select-options .option.hidden {
          display: none;
        }
      </style>
    `;

    frm.fields_dict.demo.$wrapper.html(css + html);

    let selected = [];

    window.toggleOptions = function () {
      const el = document.getElementById('multi-select-options');
      if (el) {
        el.style.display = el.style.display === 'block' ? 'none' : 'block';
      }
    };

    window.renderSelectedChips = function () {
      const selectedEl = document.getElementById('selected-values');
      selectedEl.innerHTML = '';

      selected.forEach(value => {
        const chip = document.createElement('span');
        chip.className = 'selected-chip';
        chip.innerText = value;
        chip.onclick = () => {
          updateSelection(value); // Remove on click
        };
        selectedEl.appendChild(chip);
      });

      frm.set_value('demo', selected.join(', '));
    };

    window.updateSelection = function (value) {
      if (!selected.includes(value)) {
        selected.push(value);
      } else {
        selected = selected.filter(item => item !== value);
      }

      renderSelectedChips();

      // Hide selected options from dropdown
      const options = document.querySelectorAll('.multi-select-options .option');
      options.forEach(opt => {
        const val = opt.getAttribute('data-value');
        opt.classList.toggle('hidden', selected.includes(val));
      });
    };

    setTimeout(() => {
      const options = document.querySelectorAll('.multi-select-options .option');
      options.forEach(opt => {
        opt.addEventListener('click', function (e) {
          e.stopPropagation(); // Prevent dropdown close
          const value = this.getAttribute('data-value');
          updateSelection(value);
        });
      });
    }, 100);

    document.addEventListener('click', function (event) {
      const container = document.querySelector('.multi-select-container');
      if (container && !container.contains(event.target)) {
        const dropdown = document.getElementById('multi-select-options');
        if (dropdown) dropdown.style.display = 'none';
      }
    });
  }
});

frappe.ui.form.on('Work Team', {
  validate: function(frm) {
    let employee_ids = new Set();
    let duplicates = [];

    frm.doc.team_members_list.forEach(row => {
      if (employee_ids.has(row.employee_id)) {
        duplicates.push(row.employee_id);
      }
      employee_ids.add(row.employee_id);
    });

    if (duplicates.length > 0) {
      frappe.throw(`Employee ID <b>${duplicates.join(', ')}</b> already exists. Please enter a unique ID.`);
    }
  }
});

