frappe.ui.form.on("Project Attendance", {
    end_date: function(frm) {
        validate_end_date(frm);
        calculate_naming_field(frm);
    },
    start_date: function(frm) {
        calculate_naming_field(frm);
    }
});

function validate_end_date(frm) {
    if (frm.doc.start_date && frm.doc.end_date) {
        let start = frappe.datetime.get_diff(frm.doc.end_date, frm.doc.start_date);

        if (start < 0) {
            frappe.msgprint({
                title: __("Invalid Date"),
                message: __("End Date cannot be before Start Date."),
                indicator: "red"
            });
            frm.set_value("end_date", "");  // Clear invalid value
        } else if (start > 7) {
            frappe.msgprint({
                title: __("Invalid Date Range"),
                message: __("End Date cannot be more than 7 days after Start Date."),
                indicator: "red"
            });
            frm.set_value("end_date", "");  // Clear invalid value
        }
    }
}

function calculate_naming_field(frm) {
    if (frm.doc.start_date && frm.doc.end_date) {
        let start_date = frappe.datetime.str_to_user(frm.doc.start_date);
        let end_date = frappe.datetime.str_to_user(frm.doc.end_date);

        // Extract only DD-MM format
        let start_day_month = start_date.slice(0, 5);  
        let end_day_month = end_date.slice(0, 5);

        // Set the naming field in the format: "27-03 to 28-03"
        frm.set_value("naming", `${start_day_month} to ${end_day_month}`);
    }
}

