frappe.ui.form.on("Project Attendance", {
    onload: function(frm) {
        // Restrict project selection to only "Open" status
        frm.set_query("project__client", function() {
            return {
                filters: {
                    status: "Open"
                }
            };
        });
    },

    project__client: function(frm) {
        if (frm.doc.project__client) {
            frappe.db.get_value("Project Setup", frm.doc.project__client, "status")
                .then(r => {
                    const status = r.message.status;
                    if (status !== "Open") {
                        frappe.msgprint("You can only select a project with status 'Open'.");
                        frm.set_value("project__client", null);
                    }
                });
        }
    },

    before_submit: function(frm) {
        return new Promise((resolve, reject) => {
            if (!frm.doc.project__client) {
                return resolve();
            }

            frappe.db.get_value("Project Setup", frm.doc.project__client, "status")
                .then(r => {
                    const status = r.message.status;
                    if (status !== "Open") {
                        frappe.throw("Cannot submit: The selected project is not in 'Open' status.");
                        reject();
                    } else {
                        resolve();
                    }
                });
        });
    }
});

